function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // multiple perspectives
  for (let i = 0; i < 5; i++) {
    ctx.save();
    ctx.translate(W / 2, H / 2);
    ctx.rotate(Math.sin(t + i) * Math.PI / 4);
    ctx.beginPath();
    ctx.moveTo(-50, 0);
    ctx.lineTo(50, 0);
    ctx.stroke();

    // truth stick figure
    ctx.beginPath();
    ctx.arc(0, 0, 20, 0, Math.PI * 2);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(0, 20);
    ctx.lineTo(0, 50);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(0, 30);
    ctx.lineTo(-20, 40);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(0, 30);
    ctx.lineTo(20, 40);
    ctx.stroke();
    ctx.restore();
  }

  ctx.restore();
}
